set -e
D=$(mktemp -d /tmp/login-demo.XXXX); cd $D; echo $D
npm init -y >/dev/null
npm i express express-session express-rate-limit argon2 2>&1 | tail -3
cat > server.js <<'EOF'
const crypto = require('node:crypto');
const express = require('express');
const session = require('express-session');
const { rateLimit } = require('express-rate-limit');
const argon2 = require('argon2');

if (!process.env.SESSION_SECRET) throw new Error('SESSION_SECRET is required');
const isProd = process.env.NODE_ENV === 'production';

const app = express();
if (isProd) app.set('trust proxy', 1); // one reverse proxy in front; needed for req.ip and secure cookies
app.use(express.json({ limit: '10kb' }));

app.use(session({
  name: 'sid',
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  // Default MemoryStore is for development only. Use connect-redis or similar in production.
  cookie: { httpOnly: true, secure: isProd, sameSite: 'lax', maxAge: 8 * 60 * 60 * 1000 },
}));

// Replace with a real database. Keyed by lowercased username.
const users = new Map();

// Verified against when the username is unknown, so response time does not reveal which usernames exist.
const dummyHash = argon2.hash(crypto.randomBytes(16).toString('hex'));

function credentials(req) {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string') return null;
  if (!username || username.length > 64 || password.length < 8 || password.length > 256) return null;
  return { username: username.toLowerCase(), password };
}

// Only failed attempts (status >= 400) count against the limit.
const failedLogins = {
  windowMs: 15 * 60 * 1000,
  skipSuccessfulRequests: true,
  standardHeaders: 'draft-7',
  legacyHeaders: false,
  message: { error: 'Too many failed login attempts. Try again later.' },
};
const perIp = rateLimit({ ...failedLogins, limit: 20 });
const perUsername = rateLimit({
  ...failedLogins,
  limit: 5,
  keyGenerator: (req) => `user:${String(req.body?.username).toLowerCase()}`,
});

app.post('/register', async (req, res) => {
  const creds = credentials(req);
  if (!creds) return res.status(400).json({ error: 'Invalid username or password' });
  if (users.has(creds.username)) return res.status(409).json({ error: 'Username taken' });
  const passwordHash = await argon2.hash(creds.password); // argon2id, random salt
  users.set(creds.username, { id: crypto.randomUUID(), username: creds.username, passwordHash });
  res.status(201).json({ ok: true });
});

app.post('/login', perIp, perUsername, async (req, res, next) => {
  const creds = credentials(req);
  if (!creds) return res.status(400).json({ error: 'Invalid username or password' });

  const user = users.get(creds.username);
  const ok = await argon2.verify(user ? user.passwordHash : await dummyHash, creds.password);
  if (!user || !ok) return res.status(401).json({ error: 'Invalid username or password' });

  // New session ID on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.userId = user.id;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid');
    res.json({ ok: true });
  });
});

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not authenticated' });
  next();
}

app.get('/me', requireAuth, (req, res) => {
  res.json({ userId: req.session.userId });
});

app.listen(process.env.PORT || 3000);
